def factorial(n):
    if n==0 or n==1:
        return 1
    return n*factorial(n-1)

num=int(input("Enter Number: "))
print("Factorial =",factorial(num))

def fibonacci(n):
    if n<=1:
        return n
    return fibonacci(n-1)+fibonacci(n-2)

